CREATE OR REPLACE FUNCTION public.complete_ride(p_ride_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_prev  text;
  v_remaining integer;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;

  IF p_ride_id IS NULL THEN
    RAISE EXCEPTION 'Argumentos invalidos';
  END IF;

  -- Lock the ride row
  BEGIN
    SELECT r.status
      INTO STRICT v_prev
      FROM public.rides r
     WHERE r.ride_id = p_ride_id
       FOR UPDATE;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RAISE EXCEPTION 'El viaje no existe';
  END;

  -- Only driver can complete
  IF NOT EXISTS (
    SELECT 1
      FROM public.driver_profiles dp
      JOIN public.rides rr ON rr.driver_id = dp.driver_id
     WHERE rr.ride_id = p_ride_id
       AND dp.user_id = v_actor
  ) THEN
    RAISE EXCEPTION 'Solo el conductor puede finalizar el viaje';
  END IF;

  -- Idempotent
  IF v_prev = 'completed' THEN
    RETURN;
  END IF;

  -- Validate transition
  PERFORM public.validate_ride_transition(v_prev, 'completed');

  -- Check remaining active bookings
  SELECT COUNT(*)::integer
    INTO v_remaining
    FROM public.bookings b
   WHERE b.ride_id = p_ride_id
     AND b.status IN ('confirmed', 'in_progress');

  -- Force-complete any remaining active bookings
  IF v_remaining > 0 THEN
    UPDATE public.bookings b
       SET status = 'completed'
     WHERE b.ride_id = p_ride_id
       AND b.status IN ('confirmed', 'in_progress');
  END IF;

  -- Complete the ride
  UPDATE public.rides SET status = 'completed' WHERE ride_id = p_ride_id;

  -- Close chat
  UPDATE public.chats c
     SET closed_at = timezone('utc', now())
   WHERE c.ride_id = p_ride_id
     AND c.closed_at IS NULL;

  -- History
  INSERT INTO public.ride_status_history (
    ride_id, status, previous_status, actor_id, reason
  )
  VALUES (
    p_ride_id, 'completed', v_prev, v_actor, 'manual_complete_by_driver'
  );
END;
$$;

-- Table for ride reviews / ratings
CREATE TABLE public.ride_reviews (
  review_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ride_id uuid NOT NULL REFERENCES public.rides(ride_id),
  reviewer_id uuid NOT NULL REFERENCES public.users(uuid),
  reviewee_id uuid NOT NULL REFERENCES public.users(uuid),
  rating smallint NOT NULL CHECK (rating BETWEEN 1 AND 5),
  comment text,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(ride_id, reviewer_id, reviewee_id)
);

ALTER TABLE public.ride_reviews ENABLE ROW LEVEL SECURITY;

-- RLS: users can insert their own reviews
CREATE POLICY ride_reviews_insert_own
  ON public.ride_reviews FOR INSERT
  WITH CHECK (reviewer_id = auth.uid());

-- RLS: users can read reviews involving them
CREATE POLICY ride_reviews_select_involved
  ON public.ride_reviews FOR SELECT
  USING (reviewer_id = auth.uid() OR reviewee_id = auth.uid());

-- Index for efficient avg queries
CREATE INDEX idx_ride_reviews_reviewee ON public.ride_reviews(reviewee_id);

-- Trigger function: update users.rating with cumulative average
CREATE OR REPLACE FUNCTION public.update_user_rating_on_review()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_avg numeric;
  v_is_driver boolean;
BEGIN
  -- Calculate new average for the reviewee
  SELECT AVG(r.rating)::numeric(3,2)
    INTO v_avg
    FROM public.ride_reviews r
   WHERE r.reviewee_id = NEW.reviewee_id;

  -- Update users.rating
  UPDATE public.users
     SET rating = v_avg,
         updated_at = now()
   WHERE uuid = NEW.reviewee_id;

  -- Check if reviewee is a driver, update driver_profiles.rating too
  SELECT EXISTS (
    SELECT 1 FROM public.driver_profiles dp WHERE dp.user_id = NEW.reviewee_id
  ) INTO v_is_driver;

  IF v_is_driver THEN
    UPDATE public.driver_profiles
       SET rating = v_avg
     WHERE user_id = NEW.reviewee_id;
  END IF;

  RETURN NEW;
END;
$$;

CREATE TRIGGER trg_update_user_rating
  AFTER INSERT OR UPDATE ON public.ride_reviews
  FOR EACH ROW
  EXECUTE FUNCTION public.update_user_rating_on_review();

CREATE OR REPLACE FUNCTION public.submit_review(
  p_ride_id uuid,
  p_reviewee_id uuid,
  p_rating smallint,
  p_comment text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_ride_status text;
  v_review_id uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;

  IF p_ride_id IS NULL OR p_reviewee_id IS NULL OR p_rating IS NULL THEN
    RAISE EXCEPTION 'Argumentos invalidos';
  END IF;

  IF p_rating < 1 OR p_rating > 5 THEN
    RAISE EXCEPTION 'La calificacion debe estar entre 1 y 5';
  END IF;

  IF v_actor = p_reviewee_id THEN
    RAISE EXCEPTION 'No puedes calificarte a ti mismo';
  END IF;

  -- Verify ride is completed
  SELECT r.status INTO v_ride_status
    FROM public.rides r
   WHERE r.ride_id = p_ride_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'El viaje no existe';
  END IF;

  IF v_ride_status <> 'completed' THEN
    RAISE EXCEPTION 'Solo se pueden calificar viajes completados';
  END IF;

  -- Verify reviewer participated in the ride (as driver or passenger with completed booking)
  IF NOT EXISTS (
    -- Is the driver of this ride
    SELECT 1
      FROM public.driver_profiles dp
      JOIN public.rides rr ON rr.driver_id = dp.driver_id
     WHERE rr.ride_id = p_ride_id
       AND dp.user_id = v_actor
  ) AND NOT EXISTS (
    -- Has a completed booking on this ride
    SELECT 1
      FROM public.bookings b
     WHERE b.ride_id = p_ride_id
       AND b.user_id = v_actor
       AND b.status = 'completed'
  ) THEN
    RAISE EXCEPTION 'No participaste en este viaje';
  END IF;

  -- Verify reviewee participated in the ride
  IF NOT EXISTS (
    SELECT 1
      FROM public.driver_profiles dp
      JOIN public.rides rr ON rr.driver_id = dp.driver_id
     WHERE rr.ride_id = p_ride_id
       AND dp.user_id = p_reviewee_id
  ) AND NOT EXISTS (
    SELECT 1
      FROM public.bookings b
     WHERE b.ride_id = p_ride_id
       AND b.user_id = p_reviewee_id
       AND b.status = 'completed'
  ) THEN
    RAISE EXCEPTION 'La persona a calificar no participo en este viaje';
  END IF;

  -- Upsert review
  INSERT INTO public.ride_reviews (
    ride_id, reviewer_id, reviewee_id, rating, comment
  ) VALUES (
    p_ride_id, v_actor, p_reviewee_id, p_rating, p_comment
  )
  ON CONFLICT (ride_id, reviewer_id, reviewee_id)
  DO UPDATE SET
    rating = EXCLUDED.rating,
    comment = EXCLUDED.comment,
    created_at = now()
  RETURNING review_id INTO v_review_id;

  RETURN v_review_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.request_booking(p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id        uuid;
  v_ride_id        uuid;
  v_seats          int;
  v_ride           rides%rowtype;
  v_pickup_stop    uuid;
  v_dropoff_stop   uuid;
  v_booking_id     uuid;
begin
  v_user_id := auth.uid();
  if v_user_id is null then
    raise exception 'No autenticado';
  end if;

  v_ride_id := (p_payload->>'ride_id')::uuid;
  v_seats   := coalesce((p_payload->>'seats_reserved')::int, 1);

  if v_ride_id is null then
    raise exception 'ride_id es obligatorio';
  end if;
  if v_seats < 1 then
    raise exception 'Debe reservar al menos 1 asiento';
  end if;

  select * into v_ride from rides where ride_id = v_ride_id for update;
  if not found then
    raise exception 'El viaje no existe';
  end if;

  if v_ride.status <> 'scheduled' then
    raise exception 'El viaje ya no esta disponible para reserva';
  end if;
  if v_ride.departure_time <= now() then
    raise exception 'El viaje ya partio';
  end if;
  if v_ride.available_seats < v_seats then
    raise exception 'No hay suficientes asientos disponibles';
  end if;

  if exists (
    select 1 from driver_profiles dp
    where dp.driver_id = v_ride.driver_id
      and dp.user_id   = v_user_id
  ) then
    raise exception 'No puedes reservar tu propio viaje';
  end if;

  -- Verificar que el pasajero no tenga ya un booking activo en cualquier ride
  if exists (
    select 1 from bookings
    where user_id = auth.uid()
      and status = any(array['pending', 'confirmed', 'in_progress'])
  ) then
    raise exception 'Ya tienes una reserva activa en otro viaje';
  end if;

  if exists (
    select 1 from bookings b
    where b.ride_id = v_ride_id
      and b.user_id = v_user_id
      and b.status in ('pending', 'confirmed')
  ) then
    raise exception 'Ya tienes una reserva activa para este viaje';
  end if;

  select stop_id into v_pickup_stop
  from ride_stops
  where ride_id = v_ride_id and stop_order = 1
  limit 1;

  select stop_id into v_dropoff_stop
  from ride_stops
  where ride_id = v_ride_id and stop_order = 2
  limit 1;

  if v_pickup_stop is null or v_dropoff_stop is null then
    raise exception 'El viaje no tiene paradas de origen y destino configuradas';
  end if;

  insert into bookings (
    ride_id, user_id, pickup_stop_id, dropoff_stop_id,
    seats_reserved, status
  ) values (
    v_ride_id, v_user_id, v_pickup_stop, v_dropoff_stop,
    v_seats, 'pending'
  )
  returning booking_id into v_booking_id;

  return v_booking_id;
end;
$function$;
